const scriptedProvider = (rounds: MessageChunk[][]): AIProvider => {
  let roundIndex = 0;
  return {
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      const chunks = rounds[roundIndex++] ?? [];
      for (const chunk of chunks) yield chunk;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
};

const providerWithStructured = (sendMessage: AIProvider['sendMessage']): AIProvider => ({
  sendMessage,
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

