import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {
  AIProvider,
  MessageChunk,
  SendMessageParams,
  UsageMetadata,
  Message,
  ToolResultMessage,
} from '../types/ai.js';
import {AIError} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import {ToolRegistry} from './tools/registry.js';
import type {ToolResponse} from './tools/registry.js';
import type {OutgoingMessage} from '../types/messages.js';
import type {SessionEntry} from '../types/session.js';

// Fixed: nothing asserts on it, and new Date() would tie the run to the clock.
const SENT_AT = '2026-01-01T00:00:00.000Z';

// One expect per test needs the rejection as a value rather than a matcher.
const outcomeOf = (call: Promise<unknown>): Promise<string> =>
  call.then(() => 'resolved without throwing').catch((error: Error) => error.message);

function createSession(content: string): ChatSession {
  return {
    sessionId: 's1',
    userId: 'u1',
    entries: [{role: 'user', content, timestamp: SENT_AT}],
  };
}

function createMockProvider(response: string, usage?: UsageMetadata): AIProvider {
  return {
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      yield {type: 'text', text: response};
      yield {type: 'stop', stopReason: 'end_turn', usage};
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

function createErrorProvider(error: Error): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(): AsyncGenerator<MessageChunk> {
      throw error;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

type RecordedHook =
  | 'beforeSession'
  | 'beforeUserInput'
  | 'afterUserInput'
  | 'beforeModelResponse'
  | 'afterModelResponse'
  | 'afterSession'
  | 'onError';

// Only the named hooks are installed: one that merely exists changes the observed order.
const recordingHooks = (callOrder: string[], names: RecordedHook[]): OrchestratorHooks => {
  const all: Required<OrchestratorHooks> = {
    beforeSession: async () => void callOrder.push('beforeSession'),
    beforeUserInput: async (_session, msg) => {
      callOrder.push('beforeUserInput');
      return msg;
    },
    afterUserInput: async () => void callOrder.push('afterUserInput'),
    beforeModelResponse: async (_session, systemPrompt) => {
      callOrder.push('beforeModelResponse');
      return systemPrompt;
    },
    afterModelResponse: async () => void callOrder.push('afterModelResponse'),
    afterSession: async () => void callOrder.push('afterSession'),
    onError: async () => void callOrder.push('onError'),
  };

  return Object.fromEntries(names.map(name => [name, all[name]])) as OrchestratorHooks;
};

// Records what the orchestrator actually sent, for tests that assert on the request.
const capturingProvider = (): {provider: AIProvider; sent: {systemPrompt: string; lastUserContent: string}} => {
  const sent = {systemPrompt: '', lastUserContent: ''};

  return {
    sent,
    provider: {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        sent.systemPrompt = params.systemPrompt;
        const last = params.messages[params.messages.length - 1];
        sent.lastUserContent = typeof last.content === 'string' ? last.content : '';
        yield {type: 'text', text: 'ok'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    },
  };
};

describe('createChatOrchestrator', () => {
  it('calls all hooks in correct order', async () => {
    const callOrder: string[] = [];
    const hooks = recordingHooks(callOrder, [
      'beforeSession',
      'beforeUserInput',
      'afterUserInput',
      'beforeModelResponse',
      'afterModelResponse',
      'afterSession',
    ]);

    const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('go'));

    expect(callOrder).toEqual([
      'beforeSession',
      'beforeUserInput',
      'afterUserInput',
      'beforeModelResponse',
      'afterModelResponse',
      'afterSession',
    ]);
  });

  it('called before anything else', async () => {
    const callOrder: string[] = [];
    const hooks: OrchestratorHooks = {
      beforeSession: async () => {
        callOrder.push('beforeSession');
      },
      beforeUserInput: async () => {
        callOrder.push('beforeUserInput');
        return 'go';
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('go'));

    expect(callOrder[0]).toBe('beforeSession');
  });

  it('called after everything completes', async () => {
    const callOrder: string[] = [];
    const hooks: OrchestratorHooks = {
      afterSession: async () => {
        callOrder.push('afterSession');
      },
      afterModelResponse: async () => {
        callOrder.push('afterModelResponse');
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('go'));

    expect(callOrder[callOrder.length - 1]).toBe('afterSession');
  });

  it('called even when an error occurs', async () => {
    const callOrder: string[] = [];
    const hooks: OrchestratorHooks = {
      afterSession: async () => {
        callOrder.push('afterSession');
      },
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await outcomeOf(orchestrator.processMessage(createSession('go')));

    expect(callOrder).toContain('afterSession');
  });

  it('receives the last user message content', async () => {
    let captured = '';
    const hooks: OrchestratorHooks = {
      beforeUserInput: async (_session, msg) => {
        captured = msg;
        return msg;
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('test message'));

    expect(captured).toBe('test message');
  });

  it('modifies user message when returning different value', async () => {
    const {provider, sent} = capturingProvider();
    const hooks: OrchestratorHooks = {
      beforeUserInput: async () => 'modified message',
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('original message'));

    expect(sent.lastUserContent).toBe('modified message');
  });

  it('receives user message after any beforeUserInput modification', async () => {
    let captured = '';
    const hooks: OrchestratorHooks = {
      beforeUserInput: async () => 'modified',
      afterUserInput: async (_session, msg) => {
        captured = msg;
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('original'));

    expect(captured).toBe('modified');
  });

  it('replaces system prompt with returned value', async () => {
    const {provider, sent} = capturingProvider();
    const hooks: OrchestratorHooks = {
      beforeModelResponse: async () => 'new system prompt',
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
    await orchestrator.processMessage(createSession('go'));

    expect(sent.systemPrompt).toBe('new system prompt');
  });

  it('receives collected response text and usage', async () => {
    let capturedText = '';
    let capturedUsage: UsageMetadata | undefined;
    const usage = {inputTokens: 10, outputTokens: 5, totalTokens: 15};
    const hooks: OrchestratorHooks = {
      afterModelResponse: async (_session, text, reportedUsage) => {
        capturedText = text;
        capturedUsage = reportedUsage;
      },
    };

    const orchestrator = createChatOrchestrator(createMockProvider('full response', usage), promptBuilder, undefined, {
      hooks,
    });
    await orchestrator.processMessage(createSession('go'));

    expect(capturedText).toBe('full response');
    expect(capturedUsage).toEqual(usage);
  });

  it('not called when stream throws', async () => {
    let called = false;
    const hooks: OrchestratorHooks = {
      afterModelResponse: async () => {
        called = true;
      },
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await outcomeOf(orchestrator.processMessage(createSession('go')));

    expect(called).toBe(false);
  });

  it('called with session and error when stream fails', async () => {
    let capturedError: Error | undefined;
    const error = new Error('boom');
    const hooks: OrchestratorHooks = {
      onError: async (_session, err) => {
        capturedError = err;
      },
    };

    const orchestrator = createChatOrchestrator(createErrorProvider(error), promptBuilder, undefined, {hooks});
    await outcomeOf(orchestrator.processMessage(createSession('go')));

    expect(capturedError).toBe(error);
  });

  it('error still propagates after onError hook', async () => {
    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks: {onError: async () => {}},
    });
    const message = await outcomeOf(orchestrator.processMessage(createSession('go')));

    expect(message).toBe('boom');
  });

  it('works without any hooks configured', async () => {
    const orchestrator = createChatOrchestrator(createMockProvider('ok'), promptBuilder);
    await expect(orchestrator.processMessage(createSession('go'))).resolves.not.toThrow();
  });

  it('error path calls onError then afterSession', async () => {
    const callOrder: string[] = [];
    const hooks = recordingHooks(callOrder, ['onError', 'afterSession']);

    const orchestrator = createChatOrchestrator(createErrorProvider(new Error('boom')), promptBuilder, undefined, {
      hooks,
    });
    await outcomeOf(orchestrator.processMessage(createSession('go')));

    expect(callOrder).toEqual(['onError', 'afterSession']);
  });

  describe('tool loop', () => {
    it('runs another round after a tool call and streams both rounds in order', async () => {
      const registry = new ToolRegistry();
      registry.register(
        {name: 'weather', description: 'gets weather', inputSchema: {type: 'object'}},
        async () => 'Cloudy'
      );

      const provider = scriptedProvider([
        [{type: 'text', text: 'Thinking...'}, TOOL_CALL, STOP_FOR_TOOL],
        [{type: 'text', text: ' The weather is cloudy.'}, STOP_DONE],
      ]);

      const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
      const session = createSession('What is the weather?');
      await orchestrator.processMessage(session);

      const assistantText = session.entries
        .filter(e => e.role === 'assistant')
        .map(e => e.content)
        .join('');
      expect(assistantText).toBe('Thinking... The weather is cloudy.');
    });

    it('stops after one round when nothing asked for a tool', async () => {
      const provider = scriptedProvider([[{type: 'text', text: 'done'}, STOP_DONE], [{type: 'text', text: 'never'}]]);
      const orchestrator = createChatOrchestrator(provider, promptBuilder);
      const session = createSession('go');
      await orchestrator.processMessage(session);

      expect(session.entries.length).toBe(2); // user + assistant
    });

    it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round ([validated by: hal-engine-tool-input-validation/spec.md#L45])', async () => {
      const registry = new ToolRegistry();
      let executorCalled = false;
      registry.register(
        {
          name: 'validate_me',
          description: 'A tool that needs a name',
          inputSchema: {type: 'object', required: ['name']},
        },
        async () => {
          executorCalled = true;
          return 'ok';
        }
      );

      let round = 0;
      let capturedRejection: string | undefined;
      const provider: AIProvider = {
        async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
          round++;
          if (round === 1) {
            yield {type: 'tool_use', toolCall: {id: 'c1', name: 'validate_me', input: {}}};
            yield {type: 'stop', stopReason: 'tool_use'};
            return;
          }
          if (round !== 2) {
            yield {type: 'text', text: 'all done'};
            yield {type: 'stop', stopReason: 'end_turn'};
            return;
          }

          const lastMsg = params.messages[params.messages.length - 1] as ToolResultMessage;
          const firstContent = lastMsg.content[0];
          capturedRejection = firstContent?.content;
          yield {type: 'tool_use', toolCall: {id: 'c2', name: 'validate_me', input: {name: 'fixed'}}};
          yield {type: 'stop', stopReason: 'tool_use'};
        },
        async generateStructured<T>(): Promise<T> {
          return {} as T;
        },
      };

      const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
      await orchestrator.processMessage(createSession('go'));

      expect({
        executorCalled,
        rejectionMatchesRequired: /required/i.test(capturedRejection ?? ''),
        rejectionMatchesName: /name/.test(capturedRejection ?? ''),
      }).toEqual({
        executorCalled: true,
        rejectionMatchesRequired: true,
        rejectionMatchesName: true,
      });
    });

    it('stops after max rounds even if model keeps failing validation ([validated by: hal-engine-tool-input-validation/spec.md#L49])', async () => {
      const registry = new ToolRegistry();
      registry.register(
        {
          name: 'fail_me',
          description: 'Always fails',
          inputSchema: {type: 'object', required: ['missing']},
        },
        async () => 'unreachable'
      );

      let rounds = 0;
      const lastMessages: Message[][] = [];
      const provider: AIProvider = {
        async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
          rounds++;
          lastMessages.push([...params.messages]);
          yield {type: 'tool_use', toolCall: {id: `c${rounds}`, name: 'fail_me', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
        },
